const composeHero = (...layers) => layers.reduce((acc, L) => acc.map((r, y) => [...r].map((ch, x) => (L[y][x] !== '.' ? L[y][x] : ch)).join('')));
const heroPart = (kind, want) => (HERO_PARTS[kind][want] ? want : Object.keys(HERO_PARTS[kind])[0]); // 없는 이름이면 첫 번째
const heroCostume = want => (HERO_PARTS.costume && HERO_PARTS.costume[want] ? want : '없음'); // 코스튬은 '없음'이 기본
